<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: #ffffff;
      --line: #dde4ee;
      --text: #1d2939;
      --muted: #667085;
      --accent: #3b82f6;
      --danger: #e34b4b;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font: 15px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
    }

    .app {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 42px 0;
    }

    h1 {
      margin: 0 0 22px;
      font-size: 28px;
      letter-spacing: -0.04em;
    }

    .new-task {
      display: flex;
      gap: 10px;
      margin-bottom: 24px;
    }

    #new-card {
      flex: 1;
      min-width: 0;
      padding: 12px 14px;
      border: 1px solid var(--line);
      border-radius: 9px;
      background: var(--panel);
      font: inherit;
      outline: none;
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(59, 130, 246, .15);
    }

    #add-card {
      border: 0;
      border-radius: 9px;
      padding: 0 18px;
      background: var(--accent);
      color: white;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
    }

    #add-card:hover { background: #2563eb; }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .column {
      min-height: 390px;
      display: flex;
      flex-direction: column;
      border: 1px solid var(--line);
      border-radius: 13px;
      overflow: hidden;
      background: #edf2f8;
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 15px 16px;
      background: var(--panel);
      border-bottom: 1px solid var(--line);
    }

    .column-header h2 {
      margin: 0;
      font-size: 15px;
      letter-spacing: -.01em;
    }

    .count {
      min-width: 25px;
      padding: 2px 8px;
      border-radius: 999px;
      background: #e8eef8;
      color: var(--muted);
      text-align: center;
      font-size: 12px;
      font-weight: 700;
    }

    .card-container {
      flex: 1;
      min-height: 320px;
      padding: 12px;
    }

    .column.drag-over .card-container {
      background: rgba(59, 130, 246, .09);
      outline: 2px dashed rgba(59, 130, 246, .55);
      outline-offset: -8px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 10px;
      padding: 13px;
      border: 1px solid #e1e7f0;
      border-radius: 10px;
      background: var(--panel);
      box-shadow: 0 2px 5px rgba(16, 24, 40, .06);
      cursor: grab;
      user-select: none;
    }

    .card:active { cursor: grabbing; }
    .card.dragging { opacity: .45; }

    .card-title {
      overflow-wrap: anywhere;
      user-select: text;
    }

    .card-del {
      flex: 0 0 auto;
      width: 25px;
      height: 25px;
      border: 0;
      border-radius: 6px;
      background: transparent;
      color: #98a2b3;
      font-size: 19px;
      line-height: 1;
      cursor: pointer;
    }

    .card-del:hover {
      background: #fff0f0;
      color: var(--danger);
    }

    @media (max-width: 720px) {
      .app { padding-top: 24px; }
      .board { grid-template-columns: 1fr; }
      .column { min-height: 230px; }
      .card-container { min-height: 160px; }
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>Kanban Board</h1>

    <div class="new-task">
      <input id="new-card" type="text" placeholder="What needs to be done?" aria-label="New card title">
      <button id="add-card" type="button">Add card</button>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const STORAGE_KEY = "kanban-board-state";
      const columns = ["todo", "doing", "done"];
      let board = { todo: [], doing: [], done: [] };
      let draggedCardId = null;

      function makeId() {
        return "card-" + Date.now() + "-" + Math.random().toString(36).slice(2, 9);
      }

      function loadBoard() {
        try {
          const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (saved && typeof saved === "object") {
            columns.forEach(column => {
              board[column] = Array.isArray(saved[column]) ? saved[column] : [];
            });
          }
        } catch (_) {
          board = { todo: [], doing: [], done: [] };
        }
      }

      function saveBoard() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(board));
      }

      function updateCounts() {
        columns.forEach(column => {
          const element = document.querySelector("#col-" + column + " .count");
          element.textContent = board[column].length;
        });
      }

      function deleteCard(id) {
        columns.forEach(column => {
          board[column] = board[column].filter(card => card.id !== id);
        });
        saveBoard();
        render();
      }

      function createCardElement(card) {
        const element = document.createElement("article");
        element.className = "card";
        element.draggable = true;
        element.dataset.cardId = card.id;

        const title = document.createElement("span");
        title.className = "card-title";
        title.textContent = card.title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.setAttribute("aria-label", "Delete " + card.title);
        deleteButton.textContent = "×";
        deleteButton.addEventListener("click", () => deleteCard(card.id));

        element.addEventListener("dragstart", event => {
          draggedCardId = card.id;
          element.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.id);
        });

        element.addEventListener("dragend", () => {
          draggedCardId = null;
          element.classList.remove("dragging");
          document.querySelectorAll(".column").forEach(col => col.classList.remove("drag-over"));
        });

        element.append(title, deleteButton);
        return element;
      }

      function render() {
        columns.forEach(column => {
          const container = document.querySelector("#col-" + column + " .card-container");
          container.replaceChildren(...board[column].map(createCardElement));
        });
        updateCounts();
      }

      function moveCard(id, targetColumn) {
        let movedCard = null;

        columns.forEach(column => {
          const index = board[column].findIndex(card => card.id === id);
          if (index !== -1) {
            movedCard = board[column].splice(index, 1)[0];
          }
        });

        if (movedCard) {
          board[targetColumn].push(movedCard);
          saveBoard();
          render();
        }
      }

      function addCard() {
        const input = document.getElementById("new-card");
        const title = input.value.trim();
        if (!title) return;

        board.todo.push({ id: makeId(), title });
        input.value = "";
        saveBoard();
        render();
        input.focus();
      }

      document.getElementById("add-card").addEventListener("click", addCard);
      document.getElementById("new-card").addEventListener("keydown", event => {
        if (event.key === "Enter") addCard();
      });

      document.querySelectorAll(".column").forEach(column => {
        column.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", event => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", event => {
          event.preventDefault();
          column.classList.remove("drag-over");
          const id = event.dataTransfer.getData("text/plain") || draggedCardId;
          if (id) moveCard(id, column.dataset.column);
        });
      });

      loadBoard();
      render();
    })();
  </script>
</body>
</html>
